// ─── File: RequirementsDemo.java ───
package com.bank.requirements;

import java.util.logging.*;

public class RequirementsDemo {
    private static final Logger log = Logger.getLogger("Requirements");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Functional requirements (what the system does)
        RequirementSpecification spec = new RequirementSpecification();
        spec.addFunctional("Customer can transfer money");
        spec.addFunctional("Customer can view balance");
        spec.addFunctional("Customer receives a receipt after transfer");

        // Non-functional requirements (how well)
        ServiceLevelObjective slo = new ServiceLevelObjective(200, 0.9999, true, 6000);
        spec.setSlo(slo);
        spec.print(log);

        // Simulate a measured transfer outcome
        RequestOutcome outcome = new RequestOutcome(150, true); // 150ms, consistent
        RequirementValidator validator = new RequirementValidator();
        boolean ok = validator.validate(outcome, slo, log);
        log.info(() -> "Transfer met the service level objective: " + ok);

        // Simulate a slow outcome that breaches latency
        RequestOutcome slow = new RequestOutcome(450, true);
        validator.validate(slow, slo, log);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
