// ─── File: ServiceLevelObjective.java ───
package com.bank.requirements;

public class ServiceLevelObjective {
    private final long p99LatencyMs;
    private final double availability;
    private final boolean strongConsistency;
    private final long targetPeakQps;

    public ServiceLevelObjective(long p99LatencyMs, double availability,
                                 boolean strongConsistency, long targetPeakQps) {
        this.p99LatencyMs = p99LatencyMs;
        this.availability = availability;
        this.strongConsistency = strongConsistency;
        this.targetPeakQps = targetPeakQps;
    }
    public long p99LatencyMs() { return p99LatencyMs; }
    public double availability() { return availability; }
    public boolean strongConsistency() { return strongConsistency; }
    public long targetPeakQps() { return targetPeakQps; }
}
```

