// ─── File: RequirementSpecification.java ───
package com.bank.requirements;

import java.util.*;
import java.util.logging.Logger;

public class RequirementSpecification {
    private final List<String> functional = new ArrayList<>();
    private ServiceLevelObjective slo;

    public void addFunctional(String feature) { functional.add(feature); }
    public void setSlo(ServiceLevelObjective slo) { this.slo = slo; }

    public void print(Logger log) {
        log.info("Functional requirements (what the system does):");
        functional.forEach(f -> log.info(() -> "  - " + f));
        log.info("Non-functional requirements (how well):");
        log.info(() -> "  - p99 latency <= " + slo.p99LatencyMs() + " ms");
        log.info(() -> "  - availability >= " + slo.availability());
        log.info(() -> "  - strong consistency = " + slo.strongConsistency());
        log.info(() -> "  - peak QPS target = " + slo.targetPeakQps());
    }
}
```

```java
// ─── File: RequirementValidator.java ───
package com.bank.requirements;

import java.util.logging.*;

public class RequirementValidator {

    public boolean validate(RequestOutcome outcome, ServiceLevelObjective slo, Logger log) {
        boolean latencyOk = outcome.latencyMs() <= slo.p99LatencyMs();
        boolean consistencyOk = !slo.strongConsistency() || outcome.consistent();

        if (!latencyOk)
            log.warning(() -> "Latency breach: " + outcome.latencyMs()
                + "ms > target " + slo.p99LatencyMs() + "ms");
        if (!consistencyOk)
            log.severe("Consistency breach: stale read on a money operation");

        return latencyOk && consistencyOk;
    }
}
```
